package dev.aster.charts;

import android.content.Context;
import android.os.*;
import org.json.*;
import java.io.*;
import java.util.concurrent.atomic.*;
import java.util.function.Consumer;

/** Same-platform initial sync/async preparation; never sends1m JSON numbers. */
final class PrepareBenchmark {
    private final Handler handler=new Handler(Looper.getMainLooper());private final JSONArray rows=new JSONArray();
    private Context context;private Consumer<JSONObject> completion;private AsterEngine working;private int count;private boolean finished;
    private JSONObject referenceDigest;private AsterColumns owned;private Heartbeat heartbeat;private Memory memory;
    void run(Context context,int count,Consumer<JSONObject> completion){this.context=context;this.count=count;this.completion=completion;if(count<512||count>AsterColumns.MAX_BARS){finish(new IllegalArgumentException("Prepare benchmark count limit"));return;}handler.post(this::sync);}
    void cancel(){finish(new IllegalStateException("Prepare benchmark destroyed"));}
    private JSONObject digest(AsterEngine e) throws JSONException {return new JSONObject((String)e.invoke("nativeBenchmarkDigest"));}
    private String comparable(JSONObject digest,int timeVersion) throws JSONException {JSONObject copy=new JSONObject(digest.toString());JSONObject layout=copy.getJSONObject("layout");JSONArray key=new JSONArray(layout.getString("geometryKey"));if(key.getInt(5)!=timeVersion)throw new AssertionError("Unexpected preparation time version");if(timeVersion==2)key.put(5,3);layout.put("geometryKey",key.toString());AsyncVerification.normalizeGeometryKey(layout,null);return PrepareVerification.canonical(copy);}
    private void begin(){memory=new Memory();memory.start();heartbeat=new Heartbeat();heartbeat.start();}
    private JSONObject end(long started) throws JSONException {double elapsed=(System.nanoTime()-started)/1e6;heartbeat.stop();memory.stop();return new JSONObject().put("elapsedReadySceneMs",elapsed).put("ownerHeartbeat",heartbeat.report()).put("memory",memory.report()).put("runtime",working.runtimeMetrics());}
    private void sync(){if(finished)return;try{working=new AsterEngine(context,0,PrepareVerification.options());begin();long start=System.nanoTime();working.invoke("nativeInit",count,PrepareVerification.options());PrepareVerification.indicators(working);working.scene(1200,700);JSONObject row=end(start).put("mode","sync-seeded-initial");referenceDigest=digest(working);row.put("digest",referenceDigest);rows.put(row);working.close();working=null;handler.post(()->async(false));}catch(Throwable error){finish(error);}}
    private void async(boolean columns){if(finished)return;try{working=new AsterEngine(context,0,PrepareVerification.options());PrepareVerification.indicators(working);begin();long start=System.nanoTime();AsterEngine.AsyncListener listener=new AsterEngine.AsyncListener(){@Override public void onComplete(AsterEngine.AsyncResult result){try{if(finished)return;if(result.succeeded())working.scene(1200,700);JSONObject row=end(start).put("mode",columns?"async-owned-columns-initial":"async-seeded-initial").put("job",result.toJSON());JSONObject actual=result.succeeded()?digest(working):null;boolean parity=actual!=null&&comparable(actual,3).equals(comparable(referenceDigest,2));row.put("digest",actual==null?JSONObject.NULL:actual).put("digestParity",parity);rows.put(row);if(!result.succeeded()||!parity)throw new AssertionError("Prepare benchmark result/parity "+result.status);working.close();working=null;if(columns){owned=null;finish(null);}else handler.post(PrepareBenchmark.this::buildOwnedInput);}catch(Throwable error){finish(error);}}};
        if(columns)working.prepareColumnsAsync(owned,200,new AsterEngine.AsyncOptions(120000,4096),listener);else working.prepareSeededAsync(count,42,200,new AsterEngine.AsyncOptions(120000,4096),listener);
    }catch(Throwable error){finish(error);}}
    static double[][] seeded(int count,int seed){double[][] c=new double[6][count];int state=seed;double price=100;for(int i=0;i<count;i++){double open=price;state=state*1664525+1013904223;double r=(state&0xffffffffL)/4294967296d;price=Math.max(0.1,price+(r-0.497)*1.2);c[0][i]=1700000000000d+i*60000d;c[1][i]=open;c[4][i]=price;state=state*1664525+1013904223;r=(state&0xffffffffL)/4294967296d;c[2][i]=Math.max(open,price)+r*0.6;state=state*1664525+1013904223;r=(state&0xffffffffL)/4294967296d;c[3][i]=Math.max(0.01,Math.min(open,price)-r*0.6);state=state*1664525+1013904223;r=(state&0xffffffffL)/4294967296d;c[5][i]=Math.floor(100+r*9900);}return c;}
    private void buildOwnedInput(){if(finished)return;new Thread(()->{try{long start=System.nanoTime();double[][] raw=seeded(count,42);double generation=(System.nanoTime()-start)/1e6;AsterColumns snapshot=AsterColumns.copyOf(raw[0],raw[1],raw[2],raw[3],raw[4],raw[5]);raw=null;handler.post(()->{if(finished)return;try{owned=snapshot;rows.put(new JSONObject().put("mode","caller-input-construction-background").put("generationMs",generation).put("immutableCopyMs",snapshot.copyMillis()).put("immutableOwnedBytes",snapshot.ownedBytes()).put("excludedFromNativeReadyInterval",true));async(true);}catch(Throwable error){finish(error);}});}catch(Throwable error){handler.post(()->finish(error));}},"Aster immutable input construction").start();}
    private void finish(Throwable error){if(finished)return;finished=true;if(heartbeat!=null)heartbeat.stop();if(memory!=null)memory.stop();if(working!=null){working.close();working=null;}owned=null;try{JSONObject report=new JSONObject().put("version","0.2.4").put("seed",42).put("count",count).put("indicators",new JSONArray(PrepareVerification.NAMES)).put("outputs",15).put("positions",rows).put("passed",error==null?3:0).put("androidAPI",Build.VERSION.SDK_INT).put("physicalDevice",false).put("method","one fresh source context per mode; sync generation/init +8 indicators +ready scene measured; async0-bar configuration outside interval, worker generation/validation/tree/indicators/index+commit+ready scene measured; raw input generation+immutable copy onbackground reported separately;16ms owner heartbeat includes finalinterval;50ms sampled whole-process PSS/RSS peaks; no quantiles from single samples; digest outside interval; validated per-context identity index4 normalized; lifecycle revision sync2/async3 asserted, cloned sync expected index5 advanced to3; original digests retained");if(error!=null)report.put("failed",true).put("error",error.toString());completion.accept(report);}catch(JSONException jsonError){throw new IllegalStateException(jsonError);}}
    private static final class Heartbeat {final Handler handler=new Handler(Looper.getMainLooper());long previous,max;int count;boolean stopped;final Runnable pulse=new Runnable(){@Override public void run(){if(stopped)return;long now=System.nanoTime();max=Math.max(max,now-previous);previous=now;count++;handler.postDelayed(this,16);}};void start(){previous=System.nanoTime();handler.postDelayed(pulse,16);}void stop(){if(stopped)return;max=Math.max(max,System.nanoTime()-previous);stopped=true;handler.removeCallbacks(pulse);}JSONObject report()throws JSONException{return new JSONObject().put("intervalMs",16).put("callbacks",count).put("maximumIntervalIncludingFinalMs",max/1e6);}}
    private static final class Memory {final AtomicLong pss=new AtomicLong(),rss=new AtomicLong();final AtomicInteger samples=new AtomicInteger();volatile boolean running;long beforePss,beforeRss;Thread thread;void sample(boolean force){Debug.MemoryInfo info=new Debug.MemoryInfo();Debug.getMemoryInfo(info);long r=0;try(BufferedReader in=new BufferedReader(new FileReader("/proc/self/status"))){String line;while((line=in.readLine())!=null)if(line.startsWith("VmRSS:")){r=Long.parseLong(line.substring(6).trim().split("\\s+")[0]);break;}}catch(IOException|NumberFormatException ignored){}synchronized(this){if(!force&&!running)return;maximum(pss,info.getTotalPss());maximum(rss,r);samples.incrementAndGet();}}static void maximum(AtomicLong a,long value){long old;do{old=a.get();if(old>=value)return;}while(!a.compareAndSet(old,value));}void start(){sample(true);beforePss=pss.get();beforeRss=rss.get();running=true;thread=new Thread(()->{while(running){try{Thread.sleep(50);}catch(InterruptedException stopped){break;}if(running)sample(false);}},"Aster prepare memory sampler");thread.start();}void stop(){synchronized(this){if(!running)return;running=false;}thread.interrupt();sample(true);}JSONObject report()throws JSONException{return new JSONObject().put("sampleIntervalMs",50).put("samples",samples.get()).put("processPssBeforeKiB",beforePss).put("sampledProcessPssPeakKiB",pss.get()).put("processRssBeforeKiB",beforeRss).put("sampledProcessRssPeakKiB",rss.get()).put("rssAvailable",rss.get()>0).put("scope","whole process sampled lower-bound peaks, no explicit GC");}}
}
